package com.alzz26.payments_ledger_service.ledger;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;

/**
 * Entity mapped to the "accounts" table.
 * One account per owner per currency. Has getters only (no setters).
 */
@Entity
@Table(name = "accounts")
public class Account {

    // Primary key, generated by the database on insert
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Name of the account holder
    @Column(nullable = false)
    private String owner;

    // 3-letter currency code, e.g. "INR"
    @Column(nullable = false, length = 3)
    private String currency;

    // USER or SYSTEM, stored as text
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AccountType type;

    // Creation time in UTC; excluded from UPDATE statements
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    // No-arg constructor used by JPA when loading rows
    protected Account() {
    }

    // Creates a new account and sets createdAt to the current time
    public Account(String owner, String currency, AccountType type) {
        this.owner = owner;
        this.currency = currency;
        this.type = type;
        this.createdAt = Instant.now();
    }

    public Long getId() { return this.id; }
    public String getOwner() { return this.owner; }
    public String getCurrency() { return this.currency; }
    public AccountType getType() { return this.type; }
    public Instant getCreatedAt() { return this.createdAt; }
}
